  UPDATE kb_entry
  SET published_rev = v_next,
      updated_at = NOW()
  WHERE node_id = 301 AND published_rev = v_expected;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Failed to update kb_entry for node_id=301';
  END IF;
END $$;

-- node_id=308 (S4-2.1): rev 2 -> 3
DO $$
DECLARE
  v_expected INT := 2;
  v_next INT := v_expected + 1;
  v_cur INT;
BEGIN
  SELECT published_rev INTO v_cur FROM kb_entry WHERE node_id = 308 FOR UPDATE;
  IF v_cur IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock conflict on node_id=308 (S4-2.1): expected published_rev=%, got %', v_expected, v_cur;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  VALUES (
    308,
