  SET published_rev = v_next,
      updated_at = NOW()
  WHERE node_id = 333 AND published_rev = v_expected;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Failed to update kb_entry for node_id=333';
  END IF;
