-- node_id=335 (S6-3.1): rev 2 -> 3
DO $$
DECLARE
  v_expected INT := 2;
  v_next INT := v_expected + 1;
  v_cur INT;
BEGIN
  SELECT published_rev INTO v_cur FROM kb_entry WHERE node_id = 335 FOR UPDATE;
  IF v_cur IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock conflict on node_id=335 (S6-3.1): expected published_rev=%, got %', v_expected, v_cur;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  VALUES (
    335,
    v_next,
    $z24_b_335$[{"t":"list","id":"s6-3-1-b1","imp":"core","items":["1、==网卡配置文件—文件路径==","（1）==Linux 系统下，网卡相关配置信息有专门的配置文件存储。==","（2）路径：","==ls  /etc/sysconfig/network-scripts/==一般这个文件下第一个文件==ifcfg-ens33=="],"title":"","ordered":false},{"h":260,"t":"img","w":1271,"id":"s6-3-1-b2","imp":"normal","src":"/kb-assets/skill/p163_r0_723e65eb187c8bf1.png","title":""},{"t":"list","id":"s6-3-1-b3","imp":"core","items":["==cat /etc/sysconfig/network-scripts/ifcfg-ens33=="],"title":"","ordered":false},{"h":371,"t":"img","w":498,"id":"s6-3-1-b4","imp":"normal","src":"/kb-assets/skill/p163_r1_aa1fc56519c0326d.png","title":""},{"t":"list","id":"s6-3-1-b5","imp":"core","items":["2、==网卡配置文件—初始配置状态=="],"title":"","ordered":false},{"h":613,"t":"img","w":1350,"id":"s6-3-1-b6","imp":"normal","src":"/kb-assets/skill/p163_r2_55f2af87487dc2d7.png","title":""},{"t":"list","id":"s6-3-1-b7","imp":"core","items":["3、==网卡配置文件—获取IP、网关等配置范围信息=="],"title":"","ordered":false},{"h":586,"t":"img","w":1350,"id":"s6-3-1-b8","imp":"normal","src":"/kb-assets/skill/p164_r0_e569b8756000c8ba.png","title":""},{"t":"list","id":"s6-3-1-b9","imp":"core","items":["4、==网卡配置文件—配置静态IP 信息=="],"title":"","ordered":false},{"h":662,"t":"img","w":1350,"id":"s6-3-1-b10","imp":"normal","src":"/kb-assets/skill/p164_r1_f36be063a9cc95b9.png","title":""},{"t":"list","id":"s6-3-1-b11","imp":"core","items":["5、==网卡配置文件—配置过程=="],"title":"","ordered":false},{"h":625,"t":"img","w":1350,"id":"s6-3-1-b12","imp":"normal","src":"/kb-assets/skill/p165_r0_4b25abe99ee915f3.png","title":""},{"t":"list","id":"s6-3-1-b13","imp":"core","items":["6、==网卡配置文件—测试网络状态=="],"title":"","ordered":false},{"h":644,"t":"img","w":1350,"id":"s6-3-1-b14","imp":"normal","src":"/kb-assets/skill/p165_r1_de1cbc8f4880cc4f.png","title":""},{"id":"s6-3-1-t1","t":"table","imp":"core","title":"`ifcfg-ens33` 静态网卡核心配置字段详表","headers":["配置字段","推荐值示例","字段含义与考点说明"],"rows":[["`TYPE`","`Ethernet`","网卡链路类型，以太网"],["`BOOTPROTO`","`static`","地址分配协议：==`static` 静态手工指定、`dhcp` 动态获取、`none` 不指定=="],["`NAME` / `DEVICE`","`ens33`","网络连接名称与物理设备接口名"],["`UUID`","系统生成唯一串","网卡唯一识别码"],["`ONBOOT`","`yes`","==是否开机自动激活网卡，`yes` 启用、`no` 不激活（默认常为 `no`）=="],["`IPADDR`","`192.168.177.129`","静态 IPv4 地址"],["`NETMASK`","`255.255.255.0`","子网掩码（亦可写前缀 `PREFIX=24`）"],["`GATEWAY`","`192.168.177.2`","默认网关 IP"],["`DNS1` / `DNS2`","`8.8.8.8` / `114.114.114.114`","主用与备用 DNS 服务器"]]},{"t":"list","id":"s6-3-1-b15","imp":"core","items":["7、==DNS 配置文件—文件路径与配置=="],"title":"","ordered":false},{"h":688,"t":"img","w":1350,"id":"s6-3-1-b16","imp":"normal","src":"/kb-assets/skill/p166_r0_abbf66045db41384.png","title":""},{"t":"list","id":"s6-3-1-b17","imp":"core","items":["8、主机名配置文件—文件路径与配置","9、==ifconfig 命令==：^^命令名称^^：ifconfig（interface configure） 命令所在路径：/sbin/ifconfig 执行权限：root 语法：ifconfig 网卡名称 IP地址 功能描述：查看和设置网卡信息 范例：ifconfig eth0 192.168.8.250","10、==主机名规则与 hostname 命令==：==主机名长度必须是 1～63 个字符==。 hostname 命令用法：hostname -s 显示简名，即第一个点号之前的全部名称。","11、==ADSL 接入的特点==：==ADSL 即不对称数字用户线==，俗称宽带。其特点：传输介质是电话线；价格适中；需要 ADSL Modem 连接；可同时接听、拨打电话；可始终在线；上传速度约 1 Mbps，下行速度可达 8 Mbps；有效传输距离 3～5 km。","12、^^Linux 下的网络服务^^：^^Linux 的网络功能仅次于 UNIX^^，强于 Windows NT 等系统。除 telnet、ftp、rsh、login、finger 等基本连接功能外，Linux 还能架设多种网络服务器：","1. ==邮件服务（Mail Server）==：^^最著名的是 Sendmail^^，它是负责监控和传送电子邮件的邮件代理程序，可在局域网内提供电子邮件服务，软件功能强大且完全免费，性价比高。","2. 路由与网关（Router/Gateway）：让只能访问局域网的其他计算机通过本机连接到 Internet。","13、^^传输速率的单位换算^^：^^传输速率单位为 bps（比特/秒）^^。 ==\\(1\\text{ Gb/s} = 1000\\text{ Mb/s}\\)，\\(1\\text{ Mb/s} = 1000\\text{ Kb/s} = 10^6\\text{ b/s}\\)==（注意网络传输速率换算基数为 \\(1000\\) 而非 \\(1024\\)）。","14、^^resolv.conf 配置示例^^：执行 cat /etc/resolv.conf 查看配置，示例内容为： # Generated by NetworkManager nameserver 8.8.8.8 nameserver 8.8.4.4 其中每个 nameserver 行指定一个 DNS 服务器，按顺序使用。"],"title":"","ordered":false},{"h":761,"t":"img","w":1350,"id":"s6-3-1-b18","imp":"normal","src":"/kb-assets/skill/p166_r1_40403ea86b30038c.png","title":""},{"id":"s6-3-1-m1","t":"list","imp":"core","title":"","ordered":false,"items":["15、^^网卡配置生效、DNS 解析顺序与主机名规范^^：","（1）==重启网络与连通性验证==：修改 `/etc/sysconfig/network-scripts/ifcfg-ens33` 保存退出（`vi` 下 `:wq`）后，执行 `systemctl restart network`（CentOS 7 推荐，或兼容 `service network restart`）激活配置，并用 `ping` 命令测试内网网关与外网连通性。","（2）==DNS 客户端文件 `/etc/resolv.conf` 四指令==：`nameserver` 指定 DNS 服务器 IP（可配置多行按序使用）、`domain` 定义本地默认域名、`search` 定义主机名补全搜索列表（默认包含本地域名）、`sortlist` 对返回的多个地址排序。","（3）==`/etc/hosts` 静态表优先解析与 `/etc/hostname` 规范==：系统域名解析时==优先查询 `/etc/hosts` 本地静态映射表，未命中再向 `/etc/resolv.conf` 所列 DNS 发起请求==；CentOS 7 主机名长度限于 `1~63` 个字符，仅允许字母（`a-z`/`A-Z`）、数字（`0-9`）、连字符 `-` 与点 `.`，且@@首尾必须为字母或数字（不可用 `.` 开头或结尾）@@。"]},{"id":"s6-3-1-c1","t":"code","imp":"normal","lang":"bash","code":"# 1. /etc/sysconfig/network-scripts/ifcfg-ens33\nTYPE=Ethernet\nBOOTPROTO=static\nNAME=ens33\nDEVICE=ens33\nONBOOT=yes\nIPADDR=192.168.177.129\nNETMASK=255.255.255.0\nGATEWAY=192.168.177.2\nDNS1=8.8.8.8\nDNS2=114.114.114.114\n\n# 2. /etc/hostname 与 /etc/hosts 示例\n# /etc/hostname:\nzhangzhihu\n# /etc/hosts:\n127.0.0.1   localhost zhangzhihu localhost4 zhangzhihu4\n::1         localhost zhangzhihu localhost6 zhangzhihu6","title":"CentOS 7 静态网卡、主机名与 hosts 配置文件模板"},{"t":"callout","id":"s6-3-1-b19","imp":"core","kind":"tip","text":"CentOS 7 标准网络配置文件： 1. ==网卡配置文件：`/etc/sysconfig/network-scripts/ifcfg-ens33`（配置 `BOOTPROTO=static`, `ONBOOT=yes`, `IPADDR`, `NETMASK`, `GATEWAY`, `DNS1`）==； 2. ==DNS 客户端配置文件：`/etc/resolv.conf`（指定 `nameserver` 地址）==； 3. ==主机名与映射文件：`/etc/hostname` 和 `/etc/hosts`==。","title":"考向复习提示：CentOS 7 静态网络配置三大核心配置文件"},{"t":"callout","id":"s6-3-1-b20","imp":"core","kind":"trap","text":"专转本 Linux 上机实验最高频失误点：在 `ifcfg-ens33` 中认真填好了静态 IP 和网关，但重启服务器后仍然无法联网；排查根源绝大多数在于：==网卡配置文件第一行的配置默认是 `ONBOOT=no`（表示开机不自动激活启动该网卡设备）！必须手动将该项修改为 `ONBOOT=yes`==，网卡才会在开机阶段随系统自动加载生效！","title":"高频易错陷阱：网卡配置文件中 `ONBOOT=yes` 缺失导致开机断网"}]$z24_b_335$::jsonb,
    '',
    $z24_s_335$1、网卡配置文件—文件路径
（1）Linux 系统下，网卡相关配置信息有专门的配置文件存储。
（2）路径：
ls /etc/sysconfig/network-scripts/一般这个文件下第一个文件ifcfg-ens33
cat /etc/sysconfig/network-scripts/ifcfg-ens33
2、网卡配置文件—初始配置状态
3、网卡配置文件—获取IP、网关等配置范围信息
4、网卡配置文件—配置静态IP 信息
5、网卡配置文件—配置过程
6、网卡配置文件—测试网络状态
ifcfg-ens33 静态网卡核心配置字段详表
配置字段
推荐值示例
字段含义与考点说明
TYPE
Ethernet
网卡链路类型，以太网
BOOTPROTO
static
地址分配协议：static 静态手工指定、dhcp 动态获取、none 不指定
NAME / DEVICE
ens33
网络连接名称与物理设备接口名
UUID
系统生成唯一串
网卡唯一识别码
ONBOOT
yes
是否开机自动激活网卡，yes 启用、no 不激活（默认常为 no）
IPADDR
192.168.177.129
静态 IPv4 地址
NETMASK
255.255.255.0
子网掩码（亦可写前缀 PREFIX=24）
GATEWAY
192.168.177.2
默认网关 IP
DNS1 / DNS2
8.8.8.8 / 114.114.114.114
主用与备用 DNS 服务器
7、DNS 配置文件—文件路径与配置
8、主机名配置文件—文件路径与配置
9、ifconfig 命令：命令名称：ifconfig（interface configure） 命令所在路径：/sbin/ifconfig 执行权限：root 语法：ifconfig 网卡名称 IP地址 功能描述：查看和设置网卡信息 范例：ifconfig eth0 192.168.8.250
10、主机名规则与 hostname 命令：主机名长度必须是 1～63 个字符。 hostname 命令用法：hostname -s 显示简名，即第一个点号之前的全部名称。
11、ADSL 接入的特点：ADSL 即不对称数字用户线，俗称宽带。其特点：传输介质是电话线；价格适中；需要 ADSL Modem 连接；可同时接听、拨打电话；可始终在线；上传速度约 1 Mbps，下行速度可达 8 Mbps；有效传输距离 3～5 km。
12、Linux 下的网络服务：Linux 的网络功能仅次于 UNIX，强于 Windows NT 等系统。除 telnet、ftp、rsh、login、finger 等基本连接功能外，Linux 还能架设多种网络服务器：
1. 邮件服务（Mail Server）：最著名的是 Sendmail，它是负责监控和传送电子邮件的邮件代理程序，可在局域网内提供电子邮件服务，软件功能强大且完全免费，性价比高。
2. 路由与网关（Router/Gateway）：让只能访问局域网的其他计算机通过本机连接到 Internet。
13、传输速率的单位换算：传输速率单位为 bps（比特/秒）。 1\text{ Gb/s} = 1000\text{ Mb/s}，1\text{ Mb/s} = 1000\text{ Kb/s} = 10^6\text{ b/s}（注意网络传输速率换算基数为 1000 而非 1024）。
14、resolv.conf 配置示例：执行 cat /etc/resolv.conf 查看配置，示例内容为： # Generated by NetworkManager nameserver 8.8.8.8 nameserver 8.8.4.4 其中每个 nameserver 行指定一个 DNS 服务器，按顺序使用。
15、网卡配置生效、DNS 解析顺序与主机名规范：
（1）重启网络与连通性验证：修改 /etc/sysconfig/network-scripts/ifcfg-ens33 保存退出（vi 下 :wq）后，执行 systemctl restart network（CentOS 7 推荐，或兼容 service network restart）激活配置，并用 ping 命令测试内网网关与外网连通性。
（2）DNS 客户端文件 /etc/resolv.conf 四指令：nameserver 指定 DNS 服务器 IP（可配置多行按序使用）、domain 定义本地默认域名、search 定义主机名补全搜索列表（默认包含本地域名）、sortlist 对返回的多个地址排序。
（3）/etc/hosts 静态表优先解析与 /etc/hostname 规范：系统域名解析时优先查询 /etc/hosts 本地静态映射表，未命中再向 /etc/resolv.conf 所列 DNS 发起请求；CentOS 7 主机名长度限于 1~63 个字符，仅允许字母（a-z/A-Z）、数字（0-9）、连字符 - 与点 .，且首尾必须为字母或数字（不可用 . 开头或结尾）。
CentOS 7 静态网卡、主机名与 hosts 配置文件模板
# 1. /etc/sysconfig/network-scripts/ifcfg-ens33
TYPE=Ethernet
BOOTPROTO=static
NAME=ens33
DEVICE=ens33
ONBOOT=yes
IPADDR=192.168.177.129
NETMASK=255.255.255.0
GATEWAY=192.168.177.2
DNS1=8.8.8.8
DNS2=114.114.114.114

# 2. /etc/hostname 与 /etc/hosts 示例
# /etc/hostname:
zhangzhihu
# /etc/hosts:
127.0.0.1 localhost zhangzhihu localhost4 zhangzhihu4
::1 localhost zhangzhihu localhost6 zhangzhihu6
考向复习提示：CentOS 7 静态网络配置三大核心配置文件
CentOS 7 标准网络配置文件： 1. 网卡配置文件：/etc/sysconfig/network-scripts/ifcfg-ens33（配置 BOOTPROTO=static, ONBOOT=yes, IPADDR, NETMASK, GATEWAY, DNS1）； 2. DNS 客户端配置文件：/etc/resolv.conf（指定 nameserver 地址）； 3. 主机名与映射文件：/etc/hostname 和 /etc/hosts。
高频易错陷阱：网卡配置文件中 ONBOOT=yes 缺失导致开机断网
专转本 Linux 上机实验最高频失误点：在 ifcfg-ens33 中认真填好了静态 IP 和网关，但重启服务器后仍然无法联网；排查根源绝大多数在于：网卡配置文件第一行的配置默认是 ONBOOT=no（表示开机不自动激活启动该网卡设备）！必须手动将该项修改为 ONBOOT=yes，网卡才会在开机阶段随系统自动加载生效！$z24_s_335$,
    $z24_r_335${"pdf":"操作技能复习.pdf","extra":["考纲三级节点: S6-3.1 网卡配置文件、DNS 配置文件、主机名配置文件。","题库补充：ifconfig 命令 (14题)","题库补充：主机名规则与 hostname 命令 (11题)","题库补充：ADSL 接入的特点 (10题)","题库补充：Linux 下的网络服务 (9题)","题库补充：传输速率的单位换算 (7题)","题库补充：resolv.conf 配置示例 (5题)","2024智狐《操作技能》补充：ifcfg-ens33静态网卡字段表、DNS/hosts解析优先级、主机名规范及配置文件模板"],"pages":[163,164,165,166],"spans":28}$z24_r_335$::jsonb
  );
  UPDATE kb_entry
  SET published_rev = v_next,
      updated_at = NOW()
  WHERE node_id = 335 AND published_rev = v_expected;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Failed to update kb_entry for node_id=335';
  END IF;
END $$;

-- node_id=180 (B3-3.1.2): rev 3 -> 4
DO $$
DECLARE
  v_expected INT := 3;
  v_next INT := v_expected + 1;
  v_cur INT;
BEGIN
  SELECT published_rev INTO v_cur FROM kb_entry WHERE node_id = 180 FOR UPDATE;
  IF v_cur IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock conflict on node_id=180 (B3-3.1.2): expected published_rev=%, got %', v_expected, v_cur;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  VALUES (
    180,
    v_next,
    $z24_b_180$[{"t":"list","id":"b3-3-1-2-b1","imp":"core","items":["1、==移动互联网的特征==：","(1)==交互性==：用户可以随身携带和随时使用移动终端，在移动状态下接入和使用移动互联网应用服务。","(2)==便携性==：移动终端小巧轻便、可随身携带两个特点。","(3)==隐私性==：由于移动性和便携性的特点，移动互联网的信息保护程度较高。","(4)==定位性==： 远程签到、位置共享，打车定位、导航等","(5)==娱乐性==：头条、抖音、皮皮虾、网易云音乐、当当云阅读等。","(6)==局限性==：受到了来自网络能力和终端硬件能力的限制","(7)==强关联性==：通信带宽不足时影响在线视频、视频通话，移动网游等","(8)==身份统一性==：指移动互联用户自然身份、社会身份、交易身份、支付身份通过移动互联网平台得以统一。","2、==移动互联网发展历程与关键技术==：移动互联网发展历程 ==萌芽阶段（2000—2007 年）== 手机上网（WAP）。WAP（Wireless Application Protocol，无线应用协议）是一项全球性的网络通信协议，使移动 Internet 有了通行的标准，其目标是将 Internet 的丰富信息及先进的业务引入到移动电话等无线终端之中。WAP 定义可通用的平台，把 Internet 上 HTML 语言的信息转换成用 WML（Wireless Markup Language）描述的信息，显示在移动电话的显示屏上。"],"title":"","ordered":false},{"t":"callout","id":"b3-3-1-2-b2","imp":"core","kind":"tip","text":"移动互联网核心特征概括为四化：==泛在化（随时随地 Ubiquitous）、便携化（硬件小巧随身携带）、个性化与隐私化（手机属于个人强私密设备，精准绑定用户身份与行为画像）、情境感知化（实时感知用户当前所在的地理位置、运动速度与周边环境）==。","title":"考向复习提示：移动互联网四大标志性特征口诀"},{"t":"callout","id":"b3-3-1-2-b3","imp":"core","kind":"trap","text":"传统台式机固定在办公桌上，无法提供实时动态的位置变动服务；而==移动互联网应用（如滴滴打车、美团外卖、高德地图）完全依赖于“移动网络 + 智能手机 GPS/基站定位”构成的 LBS 技术==；常考选择题考查外卖骑手路线追踪技术的核心基石，答案正是基于位置的服务 LBS！","title":"高频易错陷阱：位置服务（LBS）是移动互联网的杀手级专属能力"}]$z24_b_180$::jsonb,
    '',
    $z24_s_180$1、移动互联网的特征：
(1)交互性：用户可以随身携带和随时使用移动终端，在移动状态下接入和使用移动互联网应用服务。
(2)便携性：移动终端小巧轻便、可随身携带两个特点。
(3)隐私性：由于移动性和便携性的特点，移动互联网的信息保护程度较高。
(4)定位性： 远程签到、位置共享，打车定位、导航等
(5)娱乐性：头条、抖音、皮皮虾、网易云音乐、当当云阅读等。
(6)局限性：受到了来自网络能力和终端硬件能力的限制
(7)强关联性：通信带宽不足时影响在线视频、视频通话，移动网游等
(8)身份统一性：指移动互联用户自然身份、社会身份、交易身份、支付身份通过移动互联网平台得以统一。
2、移动互联网发展历程与关键技术：移动互联网发展历程 萌芽阶段（2000—2007 年） 手机上网（WAP）。WAP（Wireless Application Protocol，无线应用协议）是一项全球性的网络通信协议，使移动 Internet 有了通行的标准，其目标是将 Internet 的丰富信息及先进的业务引入到移动电话等无线终端之中。WAP 定义可通用的平台，把 Internet 上 HTML 语言的信息转换成用 WML（Wireless Markup Language）描述的信息，显示在移动电话的显示屏上。
考向复习提示：移动互联网四大标志性特征口诀
移动互联网核心特征概括为四化：泛在化（随时随地 Ubiquitous）、便携化（硬件小巧随身携带）、个性化与隐私化（手机属于个人强私密设备，精准绑定用户身份与行为画像）、情境感知化（实时感知用户当前所在的地理位置、运动速度与周边环境）。
高频易错陷阱：位置服务（LBS）是移动互联网的杀手级专属能力
传统台式机固定在办公桌上，无法提供实时动态的位置变动服务；而移动互联网应用（如滴滴打车、美团外卖、高德地图）完全依赖于“移动网络 + 智能手机 GPS/基站定位”构成的 LBS 技术；常考选择题考查外卖骑手路线追踪技术的核心基石，答案正是基于位置的服务 LBS！$z24_s_180$,
    $z24_r_180${"pdf":"理论复习.pdf","extra":["考纲三级节点: B3-3.1.2 移动互联网的特征。","题库补充：移动互联网发展历程与关键技术 (46题)","2024校验清理：错别字接人及违规加粗符号修复"],"pages":[111],"spans":12}$z24_r_180$::jsonb
  );
  UPDATE kb_entry
  SET published_rev = v_next,
      updated_at = NOW()
  WHERE node_id = 180 AND published_rev = v_expected;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Failed to update kb_entry for node_id=180';
  END IF;
END $$;

-- node_id=236 (B7-7.3.1): rev 2 -> 3
DO $$
DECLARE
  v_expected INT := 2;
  v_next INT := v_expected + 1;
  v_cur INT;
BEGIN
  SELECT published_rev INTO v_cur FROM kb_entry WHERE node_id = 236 FOR UPDATE;
  IF v_cur IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock conflict on node_id=236 (B7-7.3.1): expected published_rev=%, got %', v_expected, v_cur;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  VALUES (
    236,
    v_next,
    $z24_b_236$[{"t":"list","id":"b7-7-3-1-b1","imp":"core","items":["1、==区块链在金融领域应用=="],"title":"","ordered":false},{"h":537,"t":"img","w":1350,"id":"b7-7-3-1-b2","imp":"normal","src":"/kb-assets/theory/p137_r0_d8a618f6dc045996.png","title":""},{"t":"list","id":"b7-7-3-1-b3","imp":"core","items":["（1）==数字货币==：比特币是目前区块链技术最广泛、最成功的运用，在比特币基础上，又衍生出了大量其他种类的去中心化数字货币（ETH,狗狗币,莱特币等种类2000 余种）。国家发行数字货币将成趋势。","（2）==支付清算==：传统支付清算系统的处理流程过于繁琐，成本较高；区块链支付可以为交易双方直接进行端到端支付，不涉及中间机构，在提高速度和降低成本方面能得到大幅的改善。","（3）==数字票据==：一是可实现票据价值传递的去中心化；二是能够有效防范票据市场风险。","（4）==银行征信管理==：在征信领域，区块链的优势在于可依靠程序算法自动记录信用相关信息，并存储在区块链网络的每一台计算机上，信息透明、不可篡改、使用成本低。","（5）==权益证明和交易所证券交易==：在区块链系统中，交易信息具有不可篡改性和不可抵赖性。该属性可充分应用于对权益的所有者进行确权。","（6）==保险管理==：随着区块链技术的发展，未来关于个人的健康状况、发生事故记录等信息可能会上传至区块链中，使保险公司在客户投保时可以更加及时、准确地获得风险信息，从而降低核保成本、提升效率。","（7）==金融审计==：由于区块链技术能够保证所有数据的完整性、永久性和不可更改性，因而可有效解决审计行业在交易取证、追踪、关联、回溯等方面的难点和痛点。","（8）==客户征信与反欺诈==：银行的客户征信及法律合规的成本不断增加。记载于区块链中的客户信息与交易记录有助于银行识别异常交易并有效防止欺诈。","（9）==跨境支付与结算==：当前的跨境支付结算时间长、费用高、又必须通过多重中间环节。区块链将可摒弃中转银行的角色，实现点到点快速且成本低廉的跨境支付","（10）==票据与供应链金融业务==:票据及供应链金融业务因人为介入多，导致许多违规事件及操作风险。实现票据价值传递的去中介化。供应链金融也能通过区块链减少人工成本、提高安全度及实现端到端透明化。","（11）==证券发行与交易==：证券的发行与交易的流程手续繁杂且效率低下。区块链技术使得金融交易市场的参与者享用平等的数据来源，让交易流程更加公开、透明、有效率。区块链技术可准实时地记录交易者的身份、交易量等关键信息，有利于证券发行者更快速清晰地了解股权结构，提升商业决策效率；","2、==区块链在供应链领域应用==","（1）==物源追踪==：大的公司和企业在供应链都有很多的因素。因为这样，甚至对于跨国企业，追踪每个记录都是几乎不可能的。缺少透明度就导致了成本和客户关系问题，这会使得企业的名气被毁。在基于区块链的供应链管理体系中，记录存储和溯源都是很容易的，因为企业的信息可以通过内置感应器和RFID标签来获得产品信息。产品从起源地到终点所在的过程都可以通过区块链来追踪。而且，这类准确的溯源方式，可以用来检测供应链中的缺陷。","（2）==降低成本==：通过区块链，产品在供应链中的实时追踪会降低整体转移的成本。当区块链被用来加速供应链的管理流程，就会自动减少系统中多余的成本，同时还能保证交易的安全性。客户和供应商可以使用数字货币在供应链中进行支付，而不是依赖于EDI。而且，效率可以提高，产品丢失的风险也会因为准确的记录而降低。","（3）==建立信任==：在复杂的区块链中，多方间的信任很有必要。例如，当生产商和供应商分享产品，它可能会依赖于跟随工厂安全的标准。同时，当讨论到监管条例，例如海关条例，信任就会显得很重要。区块链的不可更改性可以防止造假，并且建立信任。","3、==区块链在保险领域应用==","（1）==有助于提升保险业务的安全性==：区块链技术通过加密算法实现了对客户信息的保护。","（2）==有助于缓解保险业务的信息不对称==：区块链技术通过数字化合同将信誉变成一个具有可管理的属性。","保险公司可以轻而易举地发现赔付过程中是否存在重复交易或者是否存在可疑交易当事人的交易。","（3）==基于智能合约有助于提升保险行业的效率==：智能合约可以支持自动化索赔，它是一种透明且可靠的支付机制，并且可以用来执行特定于合同的规则。","4、==区块链在教育就业领域应用==","（1）==学历证书区块链==：通过在区块链上创建类似学术成绩单和资格证书这样的记录，利用Blockcerts 可以审查文件是否可信并发现伪造的信息。","（2）==资格证书区块链==：利用区块链、智能合约以及机器学习技术来验证学生和教授的学术资格证书","（3）==知识分享区块链==：知识分享平台，学生或作者可以在上面分享和探讨小说、文学作品或者其他相关信息，可以用虚拟币（虚拟物品）奖励用户，以鼓励用户参与内容的分享、讨论和创作。这些代币可以用来购买平台上的数字化的学术书籍。","（4）==去中心化的教育产品集==： 利用区块链将教育者、学生和专业人士连接到相关的课程和资源。","（5）==竞赛成绩区块链==：支持教育机构在该平台账本上记录学生的学术成就及其他适当的信息，从而创建不可否认的学习记录。区块链帮助教育机构记录学生的数字化成绩单以及学生的支付记录。","（6）==区块链教育网络==：世界各地对区块链和数字加密货币感兴趣的学生和毕业生组成，他们分享区块链方面的思路、构建原型并上线其产品。","（7）==产学合作区块链==：教育机构与用人企业之间多赢的机制，现在教育存在的问题之一就是封闭办学、即学生的技能信息、知识体系未与用人企业的技能需求、市场趋势保持信息对称。通过引入区块链技术，实现学生技能与社会用人需求无缝衔接，可精确评估人才录用、岗位安排的科学性和合理性，能有效促进学校和企业之间的合作。","5、==区块链的通用应用==：区块链技术已经广泛应用于==生活中的各个领域==，例如金融、医疗、内容社交平台、慈善、教育、版权保护、投票等。","6、==区块链在金融、保险、教育等行业的应用现状==：==区块链在金融行业的应用尚未完全普及==，供应链金融或是一个当下切实可行的方案。 以保险行业为例，目前区块链技术仍处于早期研发和试水阶段。在传统的保险行业中，保险公司出于保护客户隐私及数据保密的商业原则，不愿意将数据资源与其他服务提供商和行政机构共享，由此极大地压缩了数据资源的开发空间。利用区块链技术的开放性，将适当的数据通过加密算法授权开放给第三方，数据使用的情况也记录在区块链上，从而实现数据的共享，避免数据滥用。开放保险在开放策略上可以对外向产业上下游开放，对内向保险业内开放，形成共赢互惠的效果。","7、==区块链在慈善行业的应用==：区块链应用于==慈善领域的核心价值是实现所有数据公开透明==。 对于慈善捐助，区块链可以让人们准确跟踪其捐款流向：捐款何时到账，最终捐款到了谁的手里。 由此，区块链可以解决慈善捐赠过程中长期存在的透明度不高和问责不清等问题。","8、==区块链提升数据安全性：公益捐赠信息公开==：==区块链可以提升数据安全性==。在公益领域，项目捐赠情况公开透明；","9、==区块链在金融行业的应用==：==区块链技术天然具有金融属性==，正对金融业产生颠覆式变革。支付结算方面，在区块链分布式账本体系下，市场多个参与者共同维护并实时同步一份“总账”，短短几分钟内就可以完成现在两三天才能完成的支付、清算、结算任务，降低了跨行跨境交易的复杂性和成本。同时，区块链的底层加密技术保证参与者无法篡改账本，确保交易记录透明安全，监管部门可以方便地追踪链上交易，快速定位高风险资金流向。","10、^^区块链在医疗领域的应用^^：区块链在医疗信息安全与隐私保护方面有着极其重要的应用。在当前中心化的信息管理系统下，各种黑客攻击和系统漏洞导致信息安全问题严重，而医疗领域存储着大量用户的私密资料，一旦发生数据泄露，后果极其严重，因此医疗领域需要严密的安全措施保护数据。 区块链去中心化的特点则有针对性地解决了这个问题。去中心化的病人医疗健康信息数据存储与共享体系的建立，大大有益于医疗行业。"],"title":"","ordered":false},{"t":"callout","id":"b7-7-3-1-b4","imp":"core","kind":"tip","text":"区块链落地赋能场景： 1. ==供应链金融（核心企业信用多级穿透，解决中小微企业融资难融资贵）==； 2. ==商品防伪溯源（农产品、奢侈品、药品全流程一物一码不可篡改流通追溯）==； 3. ==司法电子存证（网页侵权取证、电子合同上链固化时间戳秒级出证）==； 4. ==政务数据跨部门安全共享与可信身份认证==； 5. ==公益慈善捐款流向全透明公示==。","title":"考向复习提示：区块链在现代实体经济中的五大杀手级应用场景"},{"t":"callout","id":"b7-7-3-1-b5","imp":"core","kind":"trap","text":"专转本政治大纲与信息技术交叉重点考点：我国政府坚决支持并高度重视==“区块链底层核心技术的自主创新与产业实体赋能（推动区块链与实体经济深度融合）”==；但与此同时，国家监管部门==明令严厉禁止并坚决打击任何机构或个人利用区块链进行“虚拟货币发币（ICO）、炒作交易与洗钱等非法金融活动”==！二者性质截然不同！","title":"高频易错陷阱：“区块链技术”与“虚拟货币炒作”的严格法律界线"}]$z24_b_236$::jsonb,
    '',
    $z24_s_236$1、区块链在金融领域应用
（1）数字货币：比特币是目前区块链技术最广泛、最成功的运用，在比特币基础上，又衍生出了大量其他种类的去中心化数字货币（ETH,狗狗币,莱特币等种类2000 余种）。国家发行数字货币将成趋势。
（2）支付清算：传统支付清算系统的处理流程过于繁琐，成本较高；区块链支付可以为交易双方直接进行端到端支付，不涉及中间机构，在提高速度和降低成本方面能得到大幅的改善。
（3）数字票据：一是可实现票据价值传递的去中心化；二是能够有效防范票据市场风险。
（4）银行征信管理：在征信领域，区块链的优势在于可依靠程序算法自动记录信用相关信息，并存储在区块链网络的每一台计算机上，信息透明、不可篡改、使用成本低。
（5）权益证明和交易所证券交易：在区块链系统中，交易信息具有不可篡改性和不可抵赖性。该属性可充分应用于对权益的所有者进行确权。
（6）保险管理：随着区块链技术的发展，未来关于个人的健康状况、发生事故记录等信息可能会上传至区块链中，使保险公司在客户投保时可以更加及时、准确地获得风险信息，从而降低核保成本、提升效率。
（7）金融审计：由于区块链技术能够保证所有数据的完整性、永久性和不可更改性，因而可有效解决审计行业在交易取证、追踪、关联、回溯等方面的难点和痛点。
（8）客户征信与反欺诈：银行的客户征信及法律合规的成本不断增加。记载于区块链中的客户信息与交易记录有助于银行识别异常交易并有效防止欺诈。
（9）跨境支付与结算：当前的跨境支付结算时间长、费用高、又必须通过多重中间环节。区块链将可摒弃中转银行的角色，实现点到点快速且成本低廉的跨境支付
（10）票据与供应链金融业务:票据及供应链金融业务因人为介入多，导致许多违规事件及操作风险。实现票据价值传递的去中介化。供应链金融也能通过区块链减少人工成本、提高安全度及实现端到端透明化。
（11）证券发行与交易：证券的发行与交易的流程手续繁杂且效率低下。区块链技术使得金融交易市场的参与者享用平等的数据来源，让交易流程更加公开、透明、有效率。区块链技术可准实时地记录交易者的身份、交易量等关键信息，有利于证券发行者更快速清晰地了解股权结构，提升商业决策效率；
2、区块链在供应链领域应用
（1）物源追踪：大的公司和企业在供应链都有很多的因素。因为这样，甚至对于跨国企业，追踪每个记录都是几乎不可能的。缺少透明度就导致了成本和客户关系问题，这会使得企业的名气被毁。在基于区块链的供应链管理体系中，记录存储和溯源都是很容易的，因为企业的信息可以通过内置感应器和RFID标签来获得产品信息。产品从起源地到终点所在的过程都可以通过区块链来追踪。而且，这类准确的溯源方式，可以用来检测供应链中的缺陷。
（2）降低成本：通过区块链，产品在供应链中的实时追踪会降低整体转移的成本。当区块链被用来加速供应链的管理流程，就会自动减少系统中多余的成本，同时还能保证交易的安全性。客户和供应商可以使用数字货币在供应链中进行支付，而不是依赖于EDI。而且，效率可以提高，产品丢失的风险也会因为准确的记录而降低。
（3）建立信任：在复杂的区块链中，多方间的信任很有必要。例如，当生产商和供应商分享产品，它可能会依赖于跟随工厂安全的标准。同时，当讨论到监管条例，例如海关条例，信任就会显得很重要。区块链的不可更改性可以防止造假，并且建立信任。
3、区块链在保险领域应用
（1）有助于提升保险业务的安全性：区块链技术通过加密算法实现了对客户信息的保护。
（2）有助于缓解保险业务的信息不对称：区块链技术通过数字化合同将信誉变成一个具有可管理的属性。
保险公司可以轻而易举地发现赔付过程中是否存在重复交易或者是否存在可疑交易当事人的交易。
（3）基于智能合约有助于提升保险行业的效率：智能合约可以支持自动化索赔，它是一种透明且可靠的支付机制，并且可以用来执行特定于合同的规则。
4、区块链在教育就业领域应用
（1）学历证书区块链：通过在区块链上创建类似学术成绩单和资格证书这样的记录，利用Blockcerts 可以审查文件是否可信并发现伪造的信息。
（2）资格证书区块链：利用区块链、智能合约以及机器学习技术来验证学生和教授的学术资格证书
（3）知识分享区块链：知识分享平台，学生或作者可以在上面分享和探讨小说、文学作品或者其他相关信息，可以用虚拟币（虚拟物品）奖励用户，以鼓励用户参与内容的分享、讨论和创作。这些代币可以用来购买平台上的数字化的学术书籍。
（4）去中心化的教育产品集： 利用区块链将教育者、学生和专业人士连接到相关的课程和资源。
（5）竞赛成绩区块链：支持教育机构在该平台账本上记录学生的学术成就及其他适当的信息，从而创建不可否认的学习记录。区块链帮助教育机构记录学生的数字化成绩单以及学生的支付记录。
（6）区块链教育网络：世界各地对区块链和数字加密货币感兴趣的学生和毕业生组成，他们分享区块链方面的思路、构建原型并上线其产品。
（7）产学合作区块链：教育机构与用人企业之间多赢的机制，现在教育存在的问题之一就是封闭办学、即学生的技能信息、知识体系未与用人企业的技能需求、市场趋势保持信息对称。通过引入区块链技术，实现学生技能与社会用人需求无缝衔接，可精确评估人才录用、岗位安排的科学性和合理性，能有效促进学校和企业之间的合作。
5、区块链的通用应用：区块链技术已经广泛应用于生活中的各个领域，例如金融、医疗、内容社交平台、慈善、教育、版权保护、投票等。
6、区块链在金融、保险、教育等行业的应用现状：区块链在金融行业的应用尚未完全普及，供应链金融或是一个当下切实可行的方案。 以保险行业为例，目前区块链技术仍处于早期研发和试水阶段。在传统的保险行业中，保险公司出于保护客户隐私及数据保密的商业原则，不愿意将数据资源与其他服务提供商和行政机构共享，由此极大地压缩了数据资源的开发空间。利用区块链技术的开放性，将适当的数据通过加密算法授权开放给第三方，数据使用的情况也记录在区块链上，从而实现数据的共享，避免数据滥用。开放保险在开放策略上可以对外向产业上下游开放，对内向保险业内开放，形成共赢互惠的效果。
7、区块链在慈善行业的应用：区块链应用于慈善领域的核心价值是实现所有数据公开透明。 对于慈善捐助，区块链可以让人们准确跟踪其捐款流向：捐款何时到账，最终捐款到了谁的手里。 由此，区块链可以解决慈善捐赠过程中长期存在的透明度不高和问责不清等问题。
8、区块链提升数据安全性：公益捐赠信息公开：区块链可以提升数据安全性。在公益领域，项目捐赠情况公开透明；
9、区块链在金融行业的应用：区块链技术天然具有金融属性，正对金融业产生颠覆式变革。支付结算方面，在区块链分布式账本体系下，市场多个参与者共同维护并实时同步一份“总账”，短短几分钟内就可以完成现在两三天才能完成的支付、清算、结算任务，降低了跨行跨境交易的复杂性和成本。同时，区块链的底层加密技术保证参与者无法篡改账本，确保交易记录透明安全，监管部门可以方便地追踪链上交易，快速定位高风险资金流向。
10、区块链在医疗领域的应用：区块链在医疗信息安全与隐私保护方面有着极其重要的应用。在当前中心化的信息管理系统下，各种黑客攻击和系统漏洞导致信息安全问题严重，而医疗领域存储着大量用户的私密资料，一旦发生数据泄露，后果极其严重，因此医疗领域需要严密的安全措施保护数据。 区块链去中心化的特点则有针对性地解决了这个问题。去中心化的病人医疗健康信息数据存储与共享体系的建立，大大有益于医疗行业。
考向复习提示：区块链在现代实体经济中的五大杀手级应用场景
区块链落地赋能场景： 1. 供应链金融（核心企业信用多级穿透，解决中小微企业融资难融资贵）； 2. 商品防伪溯源（农产品、奢侈品、药品全流程一物一码不可篡改流通追溯）； 3. 司法电子存证（网页侵权取证、电子合同上链固化时间戳秒级出证）； 4. 政务数据跨部门安全共享与可信身份认证； 5. 公益慈善捐款流向全透明公示。
高频易错陷阱：“区块链技术”与“虚拟货币炒作”的严格法律界线
专转本政治大纲与信息技术交叉重点考点：我国政府坚决支持并高度重视“区块链底层核心技术的自主创新与产业实体赋能（推动区块链与实体经济深度融合）”；但与此同时，国家监管部门明令严厉禁止并坚决打击任何机构或个人利用区块链进行“虚拟货币发币（ICO）、炒作交易与洗钱等非法金融活动”！二者性质截然不同！$z24_s_236$,
