    RAISE EXCEPTION 'Optimistic lock conflict on node_id=237 (B7-7.3.2): expected published_rev=%, got %', v_expected, v_cur;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  VALUES (
    237,
