-- node_id=267 (S1-7.3): rev 2 -> 3
DO $$
DECLARE
  v_expected INT := 2;
  v_next INT := v_expected + 1;
  v_cur INT;
BEGIN
  SELECT published_rev INTO v_cur FROM kb_entry WHERE node_id = 267 FOR UPDATE;
  IF v_cur IS DISTINCT FROM v_expected THEN
    RAISE EXCEPTION 'Optimistic lock conflict on node_id=267 (S1-7.3): expected published_rev=%, got %', v_expected, v_cur;
  END IF;
  INSERT INTO kb_revision (node_id, rev_no, blocks, html, search_text, source_ref)
  VALUES (
